package com.proofclean.analysis.entity;
import jakarta.persistence.*;import lombok.*;import java.time.LocalDateTime;
@Entity @Table(name="detection_findings") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class DetectionFinding { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="analysis_project_id") private AnalysisProject analysisProject; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="uploaded_file_id") private UploadedFile uploadedFile; @Enumerated(EnumType.STRING) private DetectionType detectionType; private String label; @Column(columnDefinition="TEXT") private String description; private Double confidence; @Enumerated(EnumType.STRING) private Severity severity; private Double x; private Double y; private Double width; private Double height; @Column(columnDefinition="TEXT") private String extractedText; private LocalDateTime createdAt; @PrePersist void onCreate(){ createdAt=LocalDateTime.now(); } }
